package local.zft;
import android.app.Activity;
import android.graphics.*;
import android.text.*;
import android.text.style.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

final class AiArticle extends LinearLayout {
 private final Activity activity;private final ExecutorService images=Executors.newFixedThreadPool(2);private boolean closed;
 AiArticle(Activity a){super(a);activity=a;setOrientation(VERTICAL);setTag("ai.full-body");}
 void render(JSONObject item){JSONObject body=item.optJSONObject("body");String html=body==null?"":value(body,"zh");if(html.isEmpty()&&body!=null)html=value(body,"original");if(html.isEmpty()){text("新闻摘要",13,Ui.MUTED);text(value(item,"summary"),17,Ui.INK);text("该来源暂未提供完整正文",12,Ui.MUTED);}else{text(body.optString("zhKind").equals("translation")?"正文 · 中文译文":"正文",12,Ui.MUTED);html(html);if(!body.optBoolean("complete",true))text("译文尚不完整",12,Ui.MUTED);}
  JSONObject x=item.optJSONObject("x");if(x!=null){JSONArray media=x.optJSONArray("media");if(media!=null)for(int i=0;i<media.length();i++){JSONObject m=media.optJSONObject(i);if(m==null)continue;if("image".equals(m.optString("kind")))image(value(m,"url"),value(m,"alt"));else if(!value(m,"poster").isEmpty()){image(value(m,"poster"),"视频封面");text("视频封面",12,Ui.MUTED);}}}
 }
 private static String value(JSONObject o,String k){return o.isNull(k)?"":o.optString(k,"");}
 private void text(CharSequence value,int size,int color){int start=0,end=value.length();while(start<end&&Character.isWhitespace(value.charAt(start)))start++;while(end>start&&Character.isWhitespace(value.charAt(end-1)))end--;if(start==end)return;value=value.subSequence(start,end);TextView t=Ui.text(activity,"",size,color);t.setText(value);t.setTextIsSelectable(true);t.setLineSpacing(Ui.dp(activity,3),size>=17?1.25f:1);t.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_HIGH_QUALITY);t.setPadding(Ui.dp(activity,24),Ui.dp(activity,size>=17?12:8),Ui.dp(activity,24),Ui.dp(activity,size>=17?18:8));addView(t);}
 private void html(String raw){SpannableStringBuilder s=new SpannableStringBuilder(android.text.Html.fromHtml(raw,android.text.Html.FROM_HTML_MODE_LEGACY));for(QuoteSpan quote:s.getSpans(0,s.length(),QuoteSpan.class))s.removeSpan(quote);for(URLSpan link:s.getSpans(0,s.length(),URLSpan.class))s.removeSpan(link);ImageSpan[] spans=s.getSpans(0,s.length(),ImageSpan.class);Arrays.sort(spans,Comparator.comparingInt(s::getSpanStart));int offset=0;for(ImageSpan span:spans){int start=s.getSpanStart(span),end=s.getSpanEnd(span);if(start>offset)text(s.subSequence(offset,start),17,Ui.INK);image(span.getSource(),"正文配图");offset=end;}if(offset<s.length())text(s.subSequence(offset,s.length()),17,Ui.INK);}
 static URL imageUrl(String raw)throws Exception{URL u=new URL(new URL("https://aihot.news"),raw);if(!"https".equals(u.getProtocol())||!"aihot.news".equals(u.getHost())||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443))throw new IOException("Invalid image URL");return u;}
 private void image(String raw,String alt){LinearLayout block=Ui.column(activity);block.setPadding(Ui.dp(activity,24),Ui.dp(activity,12),Ui.dp(activity,24),Ui.dp(activity,24));ImageView image=new ImageView(activity);image.setAdjustViewBounds(true);image.setBackground(Ui.shape(activity,0xffeef1ed,10));image.setClipToOutline(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription(alt.isEmpty()?"新闻配图":alt);block.addView(image,new LinearLayout.LayoutParams(-1,-2));TextView state=Ui.text(activity,"图片加载中…",13,Ui.MUTED);state.setMinHeight(Ui.dp(activity,48));block.addView(state);addView(block);Runnable load=()->{state.setText("图片加载中…");state.setOnClickListener(null);images.execute(()->{try{HttpURLConnection c=(HttpURLConnection)imageUrl(raw).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","aihot-api/2.0.0");byte[] bytes;try{if(c.getResponseCode()!=200)throw new IOException("Image HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>8000000)throw new IOException("Image too large");out.write(buffer,0,n);}bytes=out.toByteArray();}}finally{c.disconnect();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Invalid image");options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1600||options.outHeight/options.inSampleSize>2400)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("Image decode failed");activity.runOnUiThread(()->{if(closed){bitmap.recycle();return;}image.setImageBitmap(bitmap);image.setTag("ai.image.loaded");state.setVisibility(GONE);});}catch(Exception e){activity.runOnUiThread(()->{if(!closed){state.setText("图片加载失败，点击重试");state.setOnClickListener(v->imageRetry(block,image,state,raw,alt));}});}});};load.run();}
 private void imageRetry(LinearLayout block,ImageView image,TextView state,String raw,String alt){int at=indexOfChild(block);removeView(block);image(raw,alt);android.view.View replacement=getChildAt(getChildCount()-1);removeView(replacement);addView(replacement,at);}
 void close(){closed=true;images.shutdownNow();}
}
